import { getHostEndpoint } from './_endpoint';
import { AUTHORIZATION_HEADER, AUTHORIZATION_VALUE } from './httpClient';
/** @public */
export const getDashboardUserEmail = async () => {
    try {
        const resp = (await getHostEndpoint().call.stripeApiFetch('/v1/user/email', {
            headers: {
                [AUTHORIZATION_HEADER]: AUTHORIZATION_VALUE,
            },
        }));
        if (resp.ok) {
            resp.email = resp.json.email;
            return resp;
        }
        return Promise.reject(resp);
    }
    catch (e) {
        console.error('Error getting dashboard user email', e);
        throw e;
    }
};
